python3 -c "print('\n\n'.join('Beta paragraph %d '%i + 'x'*120 for i in range(12)))" > $S/fixtures/beta.txt
cat > $S/e2e.mjs <<'EOF'
const S = process.argv[2];
const sleep = ms => new Promise(r => setTimeout(r, ms));
let ws, id = 0; const pending = new Map();
async function connect() {
  for (let i = 0; i < 40; i++) {
    try {
      const list = await (await fetch('http://localhost:9333/json/list')).json();
      const page = list.find(p => p.type === 'page');
      if (page) { ws = new WebSocket(page.webSocketDebuggerUrl); break; }
    } catch {}
    await sleep(250);
  }
  await new Promise(r => ws.onopen = r);
  ws.onmessage = e => { const m = JSON.parse(e.data); if (pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
}
const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async expr => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails)); return r.result.result.value; };
const clickText = t => ev(`(()=>{const b=[...document.querySelectorAll('button')].find(b=>b.textContent.trim().startsWith(${JSON.stringify(t)}));if(!b)return false;b.click();return true})()`);
async function importFile(p) {
  await clickText('+ Import'); await sleep(300);
  await send('DOM.enable');
  const { result: { root } } = await send('DOM.getDocument');
  const { result: { nodeId } } = await send('DOM.querySelector', { nodeId: root.nodeId, selector: 'input[type=file]' });
  await send('DOM.setFileInputFiles', { nodeId, files: [p] });
  await sleep(800);
}
const out = {};
await connect(); await sleep(1000);
await importFile(`${S}/fixtures/alpha.md`);
await importFile(`${S}/fixtures/beta.txt`);
out.afterImportBetaShown = await ev(`document.querySelector('[data-testid=document-content]')?.textContent.slice(0,40)`);
const docs = await ev(`window.knowledgeBase.documents.list()`);
out.docCount = docs.length;
const alpha = docs.find(d => d.filename === 'alpha.md'), beta = docs.find(d => d.filename === 'beta.txt');
// select alpha via sidebar
await ev(`(()=>{const el=[...document.querySelectorAll('*')].find(e=>e.children.length===0&&e.textContent.trim()==='alpha');el.click();return !!el})()`);
await sleep(500);
out.alphaContentMatches = (await ev(`document.querySelector('[data-testid=document-content]')?.textContent`)) === (await import('fs')).readFileSync(`${S}/fixtures/alpha.md`,'utf8');
await clickText('Hide Content'); await sleep(200);
out.hiddenAfterToggle = await ev(`!document.querySelector('[data-testid=document-content]')`);
await clickText('View Content'); await sleep(200);
out.shownAgain = await ev(`!!document.querySelector('[data-testid=document-content]')`);
out.badIdContent = await ev(`window.knowledgeBase.documents.getContent('../../documents-meta')`);
out.badIdDelete = await ev(`window.knowledgeBase.documents.delete('../x')`);
// index beta, then select it and delete with confirm
await ev(`window.knowledgeBase.indexing.start(${JSON.stringify(beta.id)})`);
await ev(`window.knowledgeBase.indexing.start()`);
await ev(`(()=>{const el=[...document.querySelectorAll('*')].find(e=>e.children.length===0&&e.textContent.trim()==='beta');el.click()})()`);
await sleep(500);
out.betaChunksLoaded = await ev(`[...document.querySelectorAll('button')].find(b=>/Chunks \\(/.test(b.textContent)).textContent`);
await clickText('Delete'); await sleep(200);
out.confirmShown = await ev(`document.body.innerText.includes('Delete this document and its data?')`);
await clickText('Cancel'); await sleep(200);
out.cancelKeepsDoc = (await ev(`window.knowledgeBase.documents.list()`)).length === 2;
await clickText('Delete'); await sleep(200);
await clickText('Confirm Delete'); await sleep(700);
out.listAfterDelete = (await ev(`window.knowledgeBase.documents.list()`)).map(d => d.filename);
out.sidebarHasBeta = await ev(`document.body.innerText.includes('beta.txt')`);
out.betaId = beta.id; out.alphaId = alpha.id;
console.log(JSON.stringify(out, null, 2));
ws.close();
EOF
echo ok

